import { TonerikoScriptSyntaxError, TonerikoScriptUnexpectedEOFError } from '../error.js';
import { decodeUnicodeEscapeSequence } from '../utils/characters.js';
import { CharStream } from './streams/char-stream.js';
import { TOKEN, TokenKind } from './token.js';
import { unexpectedTokenError } from './utils.js';

import type { ITokenStream } from './streams/token-stream.js';
import type { Token, TokenPosition } from './token.js';

const spaceChars = [' ', '\t'];
const lineBreakChars = ['\r', '\n'];
const digit = /^[0-9]$/;
const decimalDigitOrUnderscore = /^[0-9_]$/;
const hexDigitOrUnderscore = /^[0-9a-fA-F_]$/;
const binaryDigitOrUnderscore = /^[01_]$/;
const octalDigitOrUnderscore = /^[0-7_]$/;
const identifierStart = /^[A-Za-z_]$/u;
const identifierPart = /^[A-Za-z0-9_]$/u;
const hexDigit = /^[0-9a-fA-F]$/;
const exponentIndicatorPattern = /^[eE]$/;

export class Scanner implements ITokenStream {
	private stream: CharStream;
	private _tokens: Token[] = [];

	constructor(source: string);
	constructor(stream: CharStream);
	constructor(x: string | CharStream) {
		if (typeof x === 'string') {
			this.stream = new CharStream(x);
		} else {
			this.stream = x;
		}
		this._tokens.push(this.readToken());
	}

	public getToken(): Token {
		return this._tokens[0]!;
	}

	public is(kind: TokenKind): boolean {
		return this.getTokenKind() === kind;
	}

	public getTokenKind(): TokenKind {
		return this.getToken().kind;
	}

	public getTokenValue(): string {
		return this.getToken().value!;
	}

	public getPos(): TokenPosition {
		return this.getToken().pos;
	}

	public next(): void {
		if (this._tokens[0]!.kind === TokenKind.EOF) {
			return;
		}

		this._tokens.shift();

		if (this._tokens.length === 0) {
			this._tokens.push(this.readToken());
		}
	}

	public lookahead(offset: number): Token {
		while (this._tokens.length <= offset) {
			this._tokens.push(this.readToken());
		}

		return this._tokens[offset]!;
	}

	public expect(kind: TokenKind): void {
		if (!this.is(kind)) {
			throw unexpectedTokenError(this.getTokenKind(), this.getPos());
		}
	}

	private readToken(): Token {
		let hasLeftSpacing = false;

		while (true) {
			if (this.stream.eof) {
				return TOKEN(TokenKind.EOF, this.stream.getPos(), { hasLeftSpacing });
			}
			if (spaceChars.includes(this.stream.char)) {
				this.stream.next();
				hasLeftSpacing = true;
				continue;
			}

			const pos = this.stream.getPos();

			if (lineBreakChars.includes(this.stream.char)) {
				this.skipEmptyLines();
				return TOKEN(TokenKind.NewLine, pos, { hasLeftSpacing });
			}

			// 各分岐を return または continue で完結させると、noFallthroughCasesInSwitch と戻り値型の検査で未処理の分岐を検出できる。
			switch (this.stream.char) {
				case '!': {
					this.stream.next();
					if (!this.stream.eof && (this.stream.char as string) === '=') {
						this.stream.next();
						return TOKEN(TokenKind.NotEq, pos, { hasLeftSpacing });
					}
					return TOKEN(TokenKind.Not, pos, { hasLeftSpacing });
				}
				case '"':
				case "'": {
					return this.readStringLiteral(hasLeftSpacing);
				}
				case '#': {
					this.stream.next();
					if (!this.stream.eof && (this.stream.char as string) === '#') {
						this.stream.next();
						if (!this.stream.eof && (this.stream.char as string) === '#') {
							this.stream.next();
							return TOKEN(TokenKind.Sharp3, pos, { hasLeftSpacing });
						}
						throw new TonerikoScriptSyntaxError('invalid sequence of characters: "##"', pos);
					} else if (!this.stream.eof && (this.stream.char as string) === '[') {
						this.stream.next();
						return TOKEN(TokenKind.OpenSharpBracket, pos, { hasLeftSpacing });
					} else {
						return TOKEN(TokenKind.Sharp, pos, { hasLeftSpacing });
					}
				}
				case '%': {
					this.stream.next();
					return TOKEN(TokenKind.Percent, pos, { hasLeftSpacing });
				}
				case '&': {
					this.stream.next();
					if (!this.stream.eof && (this.stream.char as string) === '&') {
						this.stream.next();
						return TOKEN(TokenKind.And2, pos, { hasLeftSpacing });
					}
					throw new TonerikoScriptSyntaxError('invalid character: "&"', pos);
				}
				case '(': {
					this.stream.next();
					return TOKEN(TokenKind.OpenParen, pos, { hasLeftSpacing });
				}
				case ')': {
					this.stream.next();
					return TOKEN(TokenKind.CloseParen, pos, { hasLeftSpacing });
				}
				case '*': {
					this.stream.next();
					return TOKEN(TokenKind.Asterisk, pos, { hasLeftSpacing });
				}
				case '+': {
					this.stream.next();
					if (!this.stream.eof && (this.stream.char as string) === '=') {
						this.stream.next();
						return TOKEN(TokenKind.PlusEq, pos, { hasLeftSpacing });
					}
					return TOKEN(TokenKind.Plus, pos, { hasLeftSpacing });
				}
				case ',': {
					this.stream.next();
					return TOKEN(TokenKind.Comma, pos, { hasLeftSpacing });
				}
				case '-': {
					this.stream.next();
					if (!this.stream.eof && (this.stream.char as string) === '=') {
						this.stream.next();
						return TOKEN(TokenKind.MinusEq, pos, { hasLeftSpacing });
					}
					return TOKEN(TokenKind.Minus, pos, { hasLeftSpacing });
				}
				case '.': {
					this.stream.next();
					return TOKEN(TokenKind.Dot, pos, { hasLeftSpacing });
				}
				case '/': {
					this.stream.next();
					if (!this.stream.eof && (this.stream.char as string) === '*') {
						this.stream.next();
						this.skipCommentRange();
						continue;
					} else if (!this.stream.eof && (this.stream.char as string) === '/') {
						this.stream.next();
						this.skipCommentLine();
						continue;
					} else {
						return TOKEN(TokenKind.Slash, pos, { hasLeftSpacing });
					}
				}
				case ':': {
					this.stream.next();
					if (!this.stream.eof && (this.stream.char as string) === ':') {
						this.stream.next();
						return TOKEN(TokenKind.Colon2, pos, { hasLeftSpacing });
					}
					return TOKEN(TokenKind.Colon, pos, { hasLeftSpacing });
				}
				case ';': {
					this.stream.next();
					return TOKEN(TokenKind.SemiColon, pos, { hasLeftSpacing });
				}
				case '<': {
					this.stream.next();
					if (!this.stream.eof && (this.stream.char as string) === '=') {
						this.stream.next();
						return TOKEN(TokenKind.LtEq, pos, { hasLeftSpacing });
					} else if (!this.stream.eof && (this.stream.char as string) === ':') {
						this.stream.next();
						return TOKEN(TokenKind.Out, pos, { hasLeftSpacing });
					}
					return TOKEN(TokenKind.Lt, pos, { hasLeftSpacing });
				}
				case '=': {
					this.stream.next();
					if (!this.stream.eof && (this.stream.char as string) === '=') {
						this.stream.next();
						return TOKEN(TokenKind.Eq2, pos, { hasLeftSpacing });
					} else if (!this.stream.eof && (this.stream.char as string) === '>') {
						this.stream.next();
						return TOKEN(TokenKind.Arrow, pos, { hasLeftSpacing });
					}
					return TOKEN(TokenKind.Eq, pos, { hasLeftSpacing });
				}
				case '>': {
					this.stream.next();
					if (!this.stream.eof && (this.stream.char as string) === '=') {
						this.stream.next();
						return TOKEN(TokenKind.GtEq, pos, { hasLeftSpacing });
					}
					return TOKEN(TokenKind.Gt, pos, { hasLeftSpacing });
				}
				case '?': {
					this.stream.next();
					return TOKEN(TokenKind.Question, pos, { hasLeftSpacing });
				}
				case '@': {
					this.stream.next();
					return TOKEN(TokenKind.At, pos, { hasLeftSpacing });
				}
				case '[': {
					this.stream.next();
					return TOKEN(TokenKind.OpenBracket, pos, { hasLeftSpacing });
				}
				case '\\': {
					this.stream.next();
					if (!this.stream.eof && (this.stream.char as string) === 'u') {
						this.stream.prev();
						const wordToken = this.tryReadWord(hasLeftSpacing);
						if (wordToken) {
							return wordToken;
						}
					}
					return TOKEN(TokenKind.BackSlash, pos, { hasLeftSpacing });
				}
				case ']': {
					this.stream.next();
					return TOKEN(TokenKind.CloseBracket, pos, { hasLeftSpacing });
				}
				case '^': {
					this.stream.next();
					return TOKEN(TokenKind.Hat, pos, { hasLeftSpacing });
				}
				case '`': {
					return this.readTemplate(hasLeftSpacing);
				}
				case '{': {
					this.stream.next();
					return TOKEN(TokenKind.OpenBrace, pos, { hasLeftSpacing });
				}
				case '|': {
					this.stream.next();
					if (!this.stream.eof && (this.stream.char as string) === '|') {
						this.stream.next();
						return TOKEN(TokenKind.Or2, pos, { hasLeftSpacing });
					} else if (!this.stream.eof && (this.stream.char as string) === '>') {
						this.stream.next();
						return TOKEN(TokenKind.Pipe, pos, { hasLeftSpacing });
					}
					return TOKEN(TokenKind.Or, pos, { hasLeftSpacing });
				}
				case '}': {
					this.stream.next();
					return TOKEN(TokenKind.CloseBrace, pos, { hasLeftSpacing });
				}
				default: {
					const digitToken = this.tryReadDigits(hasLeftSpacing);
					if (digitToken) {
						return digitToken;
					}

					const wordToken = this.tryReadWord(hasLeftSpacing);
					if (wordToken) {
						return wordToken;
					}

					throw new TonerikoScriptSyntaxError(`invalid character: "${this.stream.char}"`, pos);
				}
			}
		}
	}

	private tryReadWord(hasLeftSpacing: boolean): Token | undefined {
		if (this.stream.eof) {
			return;
		}

		const pos = this.stream.getPos();

		let rawValue = this.tryReadIdentifierStart();
		if (rawValue === undefined) {
			return;
		}
		while (!(this.stream.eof as boolean)) {
			const matchedIdentifierPart = this.tryReadIdentifierPart();
			if (matchedIdentifierPart === undefined) {
				break;
			}
			rawValue += matchedIdentifierPart;
		}

		const value = decodeUnicodeEscapeSequence(rawValue);
		if (value !== rawValue) {
			throw new TonerikoScriptSyntaxError(`Invalid identifier: "${rawValue}"`, pos);
		}

		switch (value) {
			case 'null': {
				return TOKEN(TokenKind.NullKeyword, pos, { hasLeftSpacing });
			}
			case 'true': {
				return TOKEN(TokenKind.TrueKeyword, pos, { hasLeftSpacing });
			}
			case 'false': {
				return TOKEN(TokenKind.FalseKeyword, pos, { hasLeftSpacing });
			}
			case 'each': {
				return TOKEN(TokenKind.EachKeyword, pos, { hasLeftSpacing });
			}
			case 'for': {
				return TOKEN(TokenKind.ForKeyword, pos, { hasLeftSpacing });
			}
			case 'loop': {
				return TOKEN(TokenKind.LoopKeyword, pos, { hasLeftSpacing });
			}
			case 'do': {
				return TOKEN(TokenKind.DoKeyword, pos, { hasLeftSpacing });
			}
			case 'while': {
				return TOKEN(TokenKind.WhileKeyword, pos, { hasLeftSpacing });
			}
			case 'break': {
				return TOKEN(TokenKind.BreakKeyword, pos, { hasLeftSpacing });
			}
			case 'continue': {
				return TOKEN(TokenKind.ContinueKeyword, pos, { hasLeftSpacing });
			}
			case 'match': {
				return TOKEN(TokenKind.MatchKeyword, pos, { hasLeftSpacing });
			}
			case 'case': {
				return TOKEN(TokenKind.CaseKeyword, pos, { hasLeftSpacing });
			}
			case 'default': {
				return TOKEN(TokenKind.DefaultKeyword, pos, { hasLeftSpacing });
			}
			case 'if': {
				return TOKEN(TokenKind.IfKeyword, pos, { hasLeftSpacing });
			}
			case 'elif': {
				return TOKEN(TokenKind.ElifKeyword, pos, { hasLeftSpacing });
			}
			case 'else': {
				return TOKEN(TokenKind.ElseKeyword, pos, { hasLeftSpacing });
			}
			case 'return': {
				return TOKEN(TokenKind.ReturnKeyword, pos, { hasLeftSpacing });
			}
			case 'eval': {
				return TOKEN(TokenKind.EvalKeyword, pos, { hasLeftSpacing });
			}
			case 'var': {
				return TOKEN(TokenKind.VarKeyword, pos, { hasLeftSpacing });
			}
			case 'let': {
				return TOKEN(TokenKind.LetKeyword, pos, { hasLeftSpacing });
			}
			case 'exists': {
				return TOKEN(TokenKind.ExistsKeyword, pos, { hasLeftSpacing });
			}
			default: {
				return TOKEN(TokenKind.Identifier, pos, { hasLeftSpacing, value });
			}
		}
	}

	private tryReadIdentifierStart(): string | undefined {
		if (this.stream.eof) {
			return;
		}
		if (identifierStart.test(this.stream.char)) {
			const value = this.stream.char;
			this.stream.next();
			return value;
		}
		if (this.stream.char === '\\') {
			this.stream.next();
			return '\\' + this.readUnicodeEscapeSequence();
		}
		return;
	}

	private tryReadIdentifierPart(): string | undefined {
		if (this.stream.eof) {
			return;
		}
		const matchedIdentifierStart = this.tryReadIdentifierStart();
		if (matchedIdentifierStart !== undefined) {
			return matchedIdentifierStart;
		}
		if (identifierPart.test(this.stream.char)) {
			const value = this.stream.char;
			this.stream.next();
			return value;
		}
		return;
	}

	private readUnicodeEscapeSequence(): `u${string}` {
		if (this.stream.eof || (this.stream.char as string) !== 'u') {
			throw new TonerikoScriptSyntaxError('character "u" expected', this.stream.getPos());
		}
		this.stream.next();

		let code = '';
		for (let i = 0; i < 4; i++) {
			if (this.stream.eof || !hexDigit.test(this.stream.char)) {
				throw new TonerikoScriptSyntaxError('hexadecimal digit expected', this.stream.getPos());
			}
			code += this.stream.char;
			this.stream.next();
		}

		return `u${code}`;
	}

	private tryReadDigits(hasLeftSpacing: boolean): Token | undefined {
		const pos = this.stream.getPos();

		if (!this.stream.eof && this.stream.char === '0') {
			this.stream.next();
			if (!this.stream.eof && ((this.stream.char as string) === 'x' || (this.stream.char as string) === 'X')) {
				this.stream.next();
				const value = this.readRadixDigits(hexDigitOrUnderscore, pos, 'hexadecimal');
				return TOKEN(TokenKind.NumberLiteral, pos, { hasLeftSpacing, value: '0x' + value });
			}
			if (!this.stream.eof && ((this.stream.char as string) === 'b' || (this.stream.char as string) === 'B')) {
				this.stream.next();
				const value = this.readRadixDigits(binaryDigitOrUnderscore, pos, 'binary');
				return TOKEN(TokenKind.NumberLiteral, pos, { hasLeftSpacing, value: '0b' + value });
			}
			if (!this.stream.eof && ((this.stream.char as string) === 'o' || (this.stream.char as string) === 'O')) {
				this.stream.next();
				const value = this.readRadixDigits(octalDigitOrUnderscore, pos, 'octal');
				return TOKEN(TokenKind.NumberLiteral, pos, { hasLeftSpacing, value: '0o' + value });
			}
			this.stream.prev();
		}

		// 先頭の1文字は識別子(例: `_foo`)と区別するため、アンダースコアを許容しない
		if (this.stream.eof || !digit.test(this.stream.char)) {
			return;
		}
		let wholeNumber = this.stream.char;
		this.stream.next();
		while (!this.stream.eof && decimalDigitOrUnderscore.test(this.stream.char)) {
			wholeNumber += this.stream.char;
			this.stream.next();
		}
		this.validateNumericSeparators(wholeNumber, pos);

		let fractional = '';
		if (!this.stream.eof && this.stream.char === '.') {
			this.stream.next();
			if (this.stream.eof || !digit.test(this.stream.char as string)) {
				throw new TonerikoScriptSyntaxError('digit expected', pos);
			}
			fractional = this.stream.char as string;
			this.stream.next();
			while ((!this.stream.eof as boolean) && decimalDigitOrUnderscore.test(this.stream.char as string)) {
				fractional += this.stream.char;
				this.stream.next();
			}
			this.validateNumericSeparators(fractional, pos);
		}

		let exponentIndicator = '';
		let exponentSign = '';
		let exponentAbsolute = '';
		if (!this.stream.eof && exponentIndicatorPattern.test(this.stream.char as string)) {
			exponentIndicator = this.stream.char as string;
			this.stream.next();
			if (!this.stream.eof && (this.stream.char as string) === '-') {
				exponentSign = '-';
				this.stream.next();
			} else if (!this.stream.eof && (this.stream.char as string) === '+') {
				exponentSign = '+';
				this.stream.next();
			}
			if (this.stream.eof || !digit.test(this.stream.char as string)) {
				throw new TonerikoScriptSyntaxError('exponent expected', pos);
			}
			exponentAbsolute = this.stream.char as string;
			this.stream.next();
			while (!this.stream.eof && decimalDigitOrUnderscore.test(this.stream.char)) {
				exponentAbsolute += this.stream.char;
				this.stream.next();
			}
			this.validateNumericSeparators(exponentAbsolute, pos);
		}

		let value = wholeNumber.replaceAll('_', '');
		if (fractional.length > 0) {
			value += '.' + fractional.replaceAll('_', '');
		}
		if (exponentIndicator.length > 0) {
			value += exponentIndicator + exponentSign + exponentAbsolute.replaceAll('_', '');
		}
		return TOKEN(TokenKind.NumberLiteral, pos, { hasLeftSpacing, value });
	}

	private readRadixDigits(pattern: RegExp, pos: TokenPosition, radixName: string): string {
		let raw = '';
		while (!this.stream.eof && pattern.test(this.stream.char)) {
			raw += this.stream.char;
			this.stream.next();
		}
		this.validateNumericSeparators(raw, pos);
		const value = raw.replaceAll('_', '');
		if (value.length === 0) {
			throw new TonerikoScriptSyntaxError(`${radixName} digit expected`, pos);
		}
		return value;
	}

	private validateNumericSeparators(value: string, pos: TokenPosition): void {
		if (value.startsWith('_') || value.endsWith('_') || value.includes('__')) {
			throw new TonerikoScriptSyntaxError('numeric separator must be placed between digits', pos);
		}
	}

	private readStringLiteral(hasLeftSpacing: boolean): Token {
		let value = '';
		const literalMark = this.stream.char;
		let state: 'string' | 'escape' | 'finish' = 'string';

		const pos = this.stream.getPos();
		this.stream.next();

		while (state !== 'finish') {
			switch (state) {
				case 'string': {
					if (this.stream.eof) {
						throw new TonerikoScriptUnexpectedEOFError(pos);
					}
					if (this.stream.char === '\\') {
						this.stream.next();
						state = 'escape';
						break;
					}
					if (this.stream.char === literalMark) {
						this.stream.next();
						state = 'finish';
						break;
					}
					value += this.stream.char;
					this.stream.next();
					break;
				}
				case 'escape': {
					value += this.readEscapeSequence(pos);
					state = 'string';
					break;
				}
			}
		}
		return TOKEN(TokenKind.StringLiteral, pos, { hasLeftSpacing, value });
	}

	/**
	 * 呼び出し時点で先頭の `\` は消費済み。未知のエスケープは次の文字をそのまま返す。
	 */
	private readEscapeSequence(literalStartPos: TokenPosition): string {
		if (this.stream.eof) {
			throw new TonerikoScriptUnexpectedEOFError(literalStartPos);
		}
		const escapeChar = this.stream.char;
		switch (escapeChar) {
			case 'n':
				this.stream.next();
				return '\n';
			case 't':
				this.stream.next();
				return '\t';
			case 'r':
				this.stream.next();
				return '\r';
			case '0':
				this.stream.next();
				return '\0';
			case 'b':
				this.stream.next();
				return '\b';
			case 'f':
				this.stream.next();
				return '\f';
			case 'v':
				this.stream.next();
				return '\v';
			case 'u': {
				const code = this.readUnicodeEscapeSequence().slice(1);
				return String.fromCharCode(Number.parseInt(code, 16));
			}
			default: {
				this.stream.next();
				return escapeChar;
			}
		}
	}

	private readTemplate(hasLeftSpacing: boolean): Token {
		const elements: Token[] = [];
		let buf = '';
		let tokenBuf: Token[] = [];
		let state: 'string' | 'escape' | 'expr' | 'finish' = 'string';
		let exprBracketDepth = 0;

		const pos = this.stream.getPos();
		let elementPos = pos;
		this.stream.next();

		while (state !== 'finish') {
			switch (state) {
				case 'string': {
					if (this.stream.eof) {
						throw new TonerikoScriptUnexpectedEOFError(pos);
					}
					if (this.stream.char === '\\') {
						this.stream.next();
						state = 'escape';
						break;
					}
					if (this.stream.char === '`') {
						this.stream.next();
						if (buf.length > 0) {
							elements.push(TOKEN(TokenKind.TemplateStringElement, elementPos, { hasLeftSpacing, value: buf }));
						}
						state = 'finish';
						break;
					}
					if (this.stream.char === '{') {
						this.stream.next();
						if (buf.length > 0) {
							elements.push(TOKEN(TokenKind.TemplateStringElement, elementPos, { hasLeftSpacing, value: buf }));
							buf = '';
						}
						elementPos = this.stream.getPos();
						state = 'expr';
						break;
					}
					buf += this.stream.char;
					this.stream.next();
					break;
				}
				case 'escape': {
					buf += this.readEscapeSequence(pos);
					state = 'string';
					break;
				}
				case 'expr': {
					if (this.stream.eof) {
						throw new TonerikoScriptUnexpectedEOFError(pos);
					}
					if (spaceChars.includes(this.stream.char)) {
						this.stream.next();
						continue;
					}
					if (this.stream.char === '{') {
						exprBracketDepth++;
					}
					if ((this.stream.char as string) === '}') {
						if (exprBracketDepth === 0) {
							elements.push(TOKEN(TokenKind.TemplateExprElement, elementPos, { hasLeftSpacing, children: tokenBuf }));
							elementPos = this.stream.getPos();
							// 埋め込み式の解析終了を検証できるよう、Scanner が生成したトークン列に EOF を付加する。
							tokenBuf.push(TOKEN(TokenKind.EOF, elementPos));
							tokenBuf = [];
							state = 'string';
							this.stream.next();
							break;
						}
						exprBracketDepth--;
					}
					const token = this.readToken();
					tokenBuf.push(token);
					break;
				}
			}
		}

		return TOKEN(TokenKind.Template, pos, { hasLeftSpacing, children: elements });
	}

	private skipEmptyLines(): void {
		while (!this.stream.eof) {
			if (spaceChars.includes(this.stream.char) || lineBreakChars.includes(this.stream.char)) {
				this.stream.next();
				continue;
			}

			if (this.stream.char === '/') {
				this.stream.next();
				if (!this.stream.eof && (this.stream.char as string) === '*') {
					this.stream.next();
					this.skipCommentRange();
					continue;
				} else if (!this.stream.eof && (this.stream.char as string) === '/') {
					this.stream.next();
					this.skipCommentLine();
					continue;
				} else {
					this.stream.prev();
					break;
				}
			}
			break;
		}
	}

	private skipCommentLine(): void {
		while (true) {
			if (this.stream.eof) {
				break;
			}
			if (this.stream.char === '\n') {
				break;
			}
			this.stream.next();
		}
	}

	private skipCommentRange(): void {
		// 呼び出し時点で最初の`/*`は読み飛ばし済みなので、深さ1から始める
		let depth = 1;
		while (depth > 0) {
			if (this.stream.eof) {
				throw new TonerikoScriptUnexpectedEOFError(this.stream.getPos());
			}
			if (this.stream.char === '/') {
				this.stream.next();
				if (!this.stream.eof && (this.stream.char as string) === '*') {
					this.stream.next();
					depth++;
				}
				continue;
			}
			if (this.stream.char === '*') {
				this.stream.next();
				if (this.stream.eof) {
					throw new TonerikoScriptUnexpectedEOFError(this.stream.getPos());
				}
				if ((this.stream.char as string) === '/') {
					this.stream.next();
					depth--;
				}
				continue;
			}
			this.stream.next();
		}
	}
}
